-- #14 演示·极短轨迹（5 个点）
--      external_id = DEMO-014 / 5 点 / 133.3 m / 120 s
WITH ins AS (
  INSERT INTO track (name, source, external_id, start_time, end_time,
                     distance_m, duration_s, point_count, geom)
  VALUES (
    '演示·极短轨迹（5 个点）', 'demo', 'DEMO-014',
    TIMESTAMPTZ '2026-09-02 12:00:00+08' + INTERVAL '0 seconds',
    TIMESTAMPTZ '2026-09-02 12:00:00+08' + INTERVAL '120 seconds',
    133.30, 120, 5,
    ST_GeomFromText('LINESTRING(116.397500 39.909000,116.397800 39.909200,116.398000 39.909500,116.397700 39.909700,116.397500 39.909900)', 4326)
  ) RETURNING id
)
INSERT INTO track_point (track_id, seq, recorded_at, elevation_m, speed_mps, geom)
SELECT ins.id, v.seq, v.ts, v.elevation_m, v.speed_mps,
       ST_GeomFromText('POINT(' || v.lon || ' ' || v.lat || ')', 4326)
FROM ins, (VALUES
  (0, TIMESTAMPTZ '2026-09-02 12:00:00+08' + INTERVAL '0 seconds', 41.00, NULL::double precision, 116.397500, 39.909000),
  (1, TIMESTAMPTZ '2026-09-02 12:00:00+08' + INTERVAL '30 seconds', 41.10, 1.130, 116.397800, 39.909200),
  (2, TIMESTAMPTZ '2026-09-02 12:00:00+08' + INTERVAL '60 seconds', 41.20, 1.249, 116.398000, 39.909500),
  (3, TIMESTAMPTZ '2026-09-02 12:00:00+08' + INTERVAL '90 seconds', 41.30, 1.130, 116.397700, 39.909700),
  (4, TIMESTAMPTZ '2026-09-02 12:00:00+08' + INTERVAL '120 seconds', 41.40, 0.934, 116.397500, 39.909900)
) AS v(seq, ts, elevation_m, speed_mps, lon, lat);

\echo ''
\echo '########## 2) 验收：演示轨迹概览 ##########'
SELECT external_id, name, point_count,
       round(distance_m::numeric, 1) AS 距离米,
       duration_s                    AS 时长秒,
       count(*) FILTER (WHERE p.is_outlier) AS 漂移点,
       count(p.elevation_m)          AS 有海拔点数
FROM track t JOIN track_point p ON p.track_id = t.id
WHERE t.external_id LIKE 'DEMO-%'
GROUP BY external_id, name, point_count, distance_m, duration_s
ORDER BY external_id;

\echo ''
\echo '########## 3) 验收：五档各自应当非空 ##########'
-- 停留点：至少 #1、#9~#12 有段，环湖跑（#3）诚实地是 0 段
SELECT count(*) AS 演示轨迹数,
       sum(point_count) AS 演示点数
FROM track WHERE external_id LIKE 'DEMO-%';

